/**
 * 聊天页逻辑 - 精简版
 * 消息方向判断：通过 senderId 和 myOpenId 对比
 * myOpenId 获取：优先缓存 -> sendMessage返回值
 */

var commonUtil = require('../../utils/common-util.js')

var EMOJI_DATA = {
  smile: ['😀', '😂', '🤣', '😊', '😍', '🥰', '😘', '😜', '🤔', '😎', '🥺', '😭', '😤', '😡', '🤗', '😴', '🤤', '😇', '😏', '🙄', '😬', '🤐', '🤫', '🤭'],
  hand: ['👍', '👎', '👏', '🙌', '🤝', '✌️', '🤞', '👌', '💪', '👋'],
  heart: ['❤️', '💔', '💕', '💞', '💓', '💗', '💖', '💘', '💯', '✨']
}
var EMOJI_TABS = [
  { name: 'smile', icon: '😊' },
  { name: 'hand', icon: '👍' },
  { name: 'heart', icon: '❤️' }
]

Page({
  data: {
    messages: [],
    inputText: '',
    orderId: '',
    orderNo: '',
    orderInfo: null,
    scrollToId: '',
    quickReplies: ['我马上到', '可能要晚一点', '已送达门口了'],
    myOpenId: '',
    sendingImage: false,
    sending: false,
    hasMore: true,
    loadingMore: false,
    showEmoji: false,
    emojiList: [],
    emojiTabs: []
  },

  _pollTimer: null,
  _lastMsgTime: null,
  _earliestMsgTime: null,
  _pageSize: 50,

  onLoad: function (options) {
    var that = this
    var orderId = options.id
    var orderNo = options.orderNo || ''

    if (!orderId) {
      wx.showToast({ title: '缺少订单信息', icon: 'none' })
      setTimeout(function () { wx.navigateBack() }, 1500)
      return
    }

    // 检查手机号
    var cachedUser = wx.getStorageSync('userInfo')
    try { cachedUser = JSON.parse(cachedUser) } catch(e) { cachedUser = {} }
    if (!cachedUser.phone || cachedUser.phone.length !== 11) {
      wx.showModal({
        title: '需要填写手机号',
        content: '聊天功能需要先填写手机号码',
        confirmText: '去填写',
        success: function (modalRes) {
          if (modalRes.confirm) {
            wx.navigateTo({ url: '/pages/edit-profile/edit-profile' })
          }
        }
      })
      return
    }

    that.setData({ orderId: orderId, orderNo: orderNo })

    // 从缓存读取 myOpenId
    var myId = wx.getStorageSync('myOpenId')
    if (myId) that.setData({ myOpenId: myId })

    // 请求消息通知订阅
    var notifyConfig = require('../../utils/notification.js')
    wx.requestSubscribeMessage({
      tmplIds: ['aJxK4rE20mPEBeFS4LJyxTFGwsh9VK5AvqLKA6Juh-w'],
      complete: function () {}
    })

    // 加载数据
    that.loadOrderInfo(orderId)
    that.loadMessages()
  },

  onShow: function () {
    if (this.data.orderId) {
      this.loadMessages()
      this.startPolling()
    }
  },

  onHide: function () {
    this.stopPolling()
  },

  onUnload: function () {
    this.stopPolling()
  },

  startPolling: function () {
    var that = this
    this.stopPolling()
    this._pollInterval = 8000
    this._pollInactiveTime = 0
    this._pollTimer = setInterval(function () {
      that.loadNewMessages()
    }, this._pollInterval)
  },

  stopPolling: function () {
    if (this._pollTimer) {
      clearInterval(this._pollTimer)
      this._pollTimer = null
    }
  },

  adjustPollInterval: function (hasNewMessage) {
    var that = this
    if (hasNewMessage) {
      that._pollInterval = 3000
      that._pollInactiveTime = 0
    } else {
      that._pollInactiveTime += that._pollInterval
      if (that._pollInactiveTime >= 30000) {
        that._pollInterval = 15000
      } else if (that._pollInactiveTime >= 60000) {
        that._pollInterval = 20000
      }
    }
    if (that._pollTimer) {
      clearInterval(that._pollTimer)
      that._pollTimer = setInterval(function () {
        that.loadNewMessages()
      }, that._pollInterval)
    }
  },

  loadNewMessages: function () {
    var that = this
    var orderId = that.data.orderId
    var myOpenId = that.data.myOpenId
    var lastTime = that._lastMsgTime
    if (!orderId || !lastTime) return

    var db = wx.cloud.database()
    db.collection('messages').where({
      orderId: orderId,
      createTime: db.command.gt(lastTime)
    }).orderBy('createTime', 'asc').limit(20).get({
      success: function (res) {
        var list = res.data || []
        that.adjustPollInterval(list.length > 0)

        // 去重：收集已有消息ID
        var existingIds = {}
        var currentMsgs = that.data.messages
        for (var k = 0; k < currentMsgs.length; k++) {
          if (currentMsgs[k]._id && !currentMsgs[k]._id.startsWith('temp_')) {
            existingIds[currentMsgs[k]._id] = true
          }
        }

        var newMsgs = []
        for (var i = 0; i < list.length; i++) {
          var m = list[i]
          // 跳过已存在的消息（去重）
          if (existingIds[m._id]) continue

          var isMine = !!(myOpenId && m.senderId && m.senderId === myOpenId)
          newMsgs.push({
            _id: m._id,
            content: m.content || '',
            imageUrl: m.imageUrl || '',
            isMine: isMine,
            senderName: m.senderName || '对方',
            isReadByOther: !!m.isRead,
            showReadStatus: false,
            createTime: m.createTime,
            showTime: false,
            timeText: that.formatTime(m.createTime),
            sendFailed: false
          })
          var msgTime = new Date(m.createTime).getTime()
          if (msgTime > new Date(that._lastMsgTime).getTime()) {
            that._lastMsgTime = m.createTime
          }
        }

        if (newMsgs.length === 0) return

        var allMsgs = that.data.messages.concat(newMsgs)
        that.setData({ messages: allMsgs })
        that.scrollToBottom()
        that.markRead()
        that.convertChatImages(allMsgs)
      },
      fail: function () {}
    })
  },

  // 加载订单信息
  loadOrderInfo: function (orderId) {
    var that = this
    var myOpenId = that.data.myOpenId || wx.getStorageSync('myOpenId') || ''
    wx.cloud.database().collection('orders').doc(orderId).get({
      success: function (res) {
        var order = res.data || {}
        var chatTargetName = ''
        // 判断当前用户身份，显示对方名称
        if (myOpenId && order.publisherId === myOpenId) {
          // 当前是发布者，显示接单人名称
          chatTargetName = order.acceptorName || '接单人'
        } else if (myOpenId && order.acceptorId === myOpenId) {
          // 当前是接单人，显示发布者名称
          chatTargetName = order.publisherName || '发布者'
        } else {
          chatTargetName = order.publisherName || '用户'
        }
        that.setData({
          orderInfo: order,
          chatTargetName: chatTargetName
        })
      },
      fail: function () {
        wx.showToast({ title: '订单加载失败', icon: 'none' })
      }
    })
  },

  // 转换聊天图片 fileID 为临时 URL（使用公共模块，带缓存）
  convertChatImages: function(messages) {
    var that = this
    commonUtil.convertChatImages(messages).then(function() {
      that.setData({ messages: messages })
    })
  },

  formatMessages: function (list, myOpenId) {
    var that = this
    var messages = []
    var lastMineIdx = -1

    for (var k = list.length - 1; k >= 0; k--) {
      if (myOpenId && list[k].senderId === myOpenId) { lastMineIdx = k; break }
    }

    for (var i = 0; i < list.length; i++) {
      var m = list[i]
      var isMine = !!(myOpenId && m.senderId && m.senderId === myOpenId)
      messages.push({
        _id: m._id,
        content: m.content || '',
        imageUrl: m.imageUrl || '',
        isMine: isMine,
        senderName: m.senderName || '对方',
        isReadByOther: !!m.isRead,
        showReadStatus: (isMine && i === lastMineIdx),
        createTime: m.createTime,
        showTime: i === 0 || (m.createTime - list[i - 1].createTime > 300000),
        timeText: that.formatTime(m.createTime),
        sendFailed: false
      })
    }
    return messages
  },

  // 加载最新消息
  loadMessages: function () {
    var that = this
    var orderId = that.data.orderId
    var myOpenId = that.data.myOpenId
    var pageSize = that._pageSize

    wx.cloud.database().collection('messages').where({
      orderId: orderId
    }).orderBy('createTime', 'desc').limit(pageSize).get({
      success: function (res) {
        var list = res.data || []
        list.reverse()
        var messages = that.formatMessages(list, myOpenId)

        if (list.length > 0) {
          that._lastMsgTime = list[list.length - 1].createTime
          that._earliestMsgTime = list[0].createTime
        }
        var hasMore = list.length >= pageSize
        that.setData({ messages: messages, hasMore: hasMore })
        that.scrollToBottom()
        setTimeout(function () { that.markRead() }, 500)
        that.convertChatImages(messages)
      },
      fail: function () {
        wx.showToast({ title: '消息加载失败，请下拉重试', icon: 'none' })
      }
    })
  },

  // 加载更多历史消息
  loadMoreMessages: function () {
    var that = this
    if (that.data.loadingMore || !that.data.hasMore || !that._earliestMsgTime) return

    that.setData({ loadingMore: true })
    var orderId = that.data.orderId
    var myOpenId = that.data.myOpenId
    var pageSize = that._pageSize
    var _ = wx.cloud.database().command

    wx.cloud.database().collection('messages').where({
      orderId: orderId,
      createTime: _.lt(that._earliestMsgTime)
    }).orderBy('createTime', 'desc').limit(pageSize).get({
      success: function (res) {
        var list = res.data || []
        list.reverse()
        if (list.length > 0) {
          var oldMessages = that.data.messages
          var newMessages = that.formatMessages(list, myOpenId)
          // 更新旧消息的showTime
          if (oldMessages.length > 0) {
            oldMessages[0].showTime = oldMessages[0].createTime - list[list.length - 1].createTime > 300000
          }
          var allMessages = newMessages.concat(oldMessages)
          that._earliestMsgTime = list[0].createTime
          var hasMore = list.length >= pageSize
          that.setData({ messages: allMessages, hasMore: hasMore, loadingMore: false })
          that.convertChatImages(newMessages)
        } else {
          that.setData({ hasMore: false, loadingMore: false })
        }
      },
      fail: function () {
        that.setData({ loadingMore: false })
        wx.showToast({ title: '加载失败', icon: 'none' })
      }
    })
  },

  // 标记已读
  markRead: function () {
    var orderId = this.data.orderId
    if (!orderId) return
    wx.cloud.callFunction({
      name: 'markMessagesRead',
      data: { orderId: orderId },
      fail: function () {}
    })
  },

  // 格式化时间
  formatTime: function (t) {
    if (!t) return ''
    var d = new Date(t)
    var now = new Date()
    var h = d.getHours(), m = d.getMinutes()
    var ts = (h < 10 ? '0' : '') + h + ':' + (m < 10 ? '0' : '') + m
    if (d.toDateString() === now.toDateString()) return ts
    var y = new Date(now.getTime() - 86400000)
    if (d.toDateString() === y.toDateString()) return '昨天 ' + ts
    return (d.getMonth() + 1) + '/' + d.getDate() + ' ' + ts
  },

  // 输入
  onInput: function (e) {
    this.setData({ inputText: e.detail.value })
  },

  // 发送文字
  sendMessage: function () {
    var that = this
    var content = (that.data.inputText || '').trim()
    if (!content) return

    // 防止重复发送
    if (that.data.sending) return

    var orderId = that.data.orderId
    that.setData({ inputText: '', sending: true })

    // 乐观添加（带发送中状态）
    var tempId = 'temp_' + Date.now()
    var msgs = that.data.messages
    msgs.push({
      _id: tempId, content: content, imageUrl: '', isMine: true,
      senderName: '我', createTime: Date.now(), showTime: msgs.length === 0,
      timeText: that.formatTime(Date.now()), isReadByOther: false, showReadStatus: true,
      sendFailed: false
    })
    that.setData({ messages: msgs })
    that.scrollToBottom()

    // 调用云函数
    wx.cloud.callFunction({
      name: 'sendMessage',
      data: { orderId: orderId, content: content },
      success: function (res) {
        var r = res.result
        if (r && r.code === 0) {
          // 缓存真实的 senderId
          var sid = r.data && r.data.senderId
          if (sid && !that.data.myOpenId) {
            that.setData({ myOpenId: sid, sending: false })
            wx.setStorageSync('myOpenId', sid)
            // 重新加载前先清除临时消息，防止重复
            var msgs = that.data.messages.filter(function(m) {
              return !m._id || !m._id.startsWith('temp_')
            })
            that.setData({ messages: msgs })
            setTimeout(function () { that.loadMessages() }, 300)
            return
          }
          // 更新临时消息ID，清除发送中状态
          var ms = that.data.messages
          for (var i = ms.length - 1; i >= 0; i--) {
            if (ms[i]._id === tempId) {
              ms[i]._id = r.data._id
              ms[i].sendFailed = false
              break
            }
          }
          that.setData({ messages: ms, sending: false })
        } else {
          wx.showToast({ title: (r && r.msg) || '发送失败', icon: 'none' })
          // 标记消息发送失败（不删除，允许重试）
          var ms2 = that.data.messages
          for (var j = ms2.length - 1; j >= 0; j--) {
            if (ms2[j]._id === tempId) {
              ms2[j].sendFailed = true
              break
            }
          }
          that.setData({ messages: ms2, sending: false })
        }
      },
      fail: function () {
        wx.showToast({ title: '发送失败', icon: 'none' })
        // 标记消息发送失败（保留消息，允许重试）
        var ms = that.data.messages
        for (var i = ms.length - 1; i >= 0; i--) {
          if (ms[i]._id === tempId) {
            ms[i].sendFailed = true
            break
          }
        }
        that.setData({ messages: ms, sending: false })
      }
    })
  },

  // 重试发送失败的消息
  retryMessage: function (e) {
    var index = e.currentTarget.dataset.index
    var msg = this.data.messages[index]
    if (!msg || !msg.sendFailed) return

    var that = this
    var content = msg.content
    var orderId = that.data.orderId

    // 移除失败消息
    var ms = that.data.messages
    ms.splice(index, 1)
    that.setData({ messages: ms })

    // 重新发送
    that.setData({ inputText: content })
    that.sendMessage()
  },

  // 快捷回复
  onQuickReply: function (e) {
    this.setData({ inputText: e.currentTarget.dataset.text || '' })
    this.sendMessage()
  },

  // 滚动到底部
  scrollToBottom: function () {
    var that = this
    setTimeout(function () { that.setData({ scrollToId: '' }) }, 50)
    setTimeout(function () { that.setData({ scrollToId: 'msg-bottom' }) }, 100)
  },

  // 选择图片
  chooseImage: function () {
    var that = this
    wx.chooseImage({
      count: 1, sizeType: ['compressed'], sourceType: ['album', 'camera'],
      success: function (res) { that.uploadImage(res.tempFilePaths[0]) }
    })
  },

  // 上传图片并发送（先压缩到100KB以内）
  uploadImage: function (path) {
    var that = this
    that.setData({ sendingImage: true })
    // 先压缩图片
    commonUtil.compressImageToSize(path, 100).then(function(compressedPath) {
      wx.cloud.uploadFile({
        cloudPath: 'chat-images/' + Date.now() + Math.floor(Math.random() * 9999) + '.jpg',
        filePath: compressedPath,
        success: function (up) {
          wx.cloud.callFunction({
            name: 'sendMessage',
            data: { orderId: that.data.orderId, content: '[图片]', imageUrl: up.fileID },
            success: function (res) {
              var r = res.result
              if (r && r.code === 0) {
                var msgs = that.data.messages
                msgs.push({
                  _id: r.data._id, content: '', imageUrl: up.fileID, isMine: true,
                  senderName: '我', createTime: Date.now(), showTime: false,
                  timeText: that.formatTime(Date.now()), isReadByOther: false, showReadStatus: true,
                  sendFailed: false
                })
                that.setData({ messages: msgs })
                that.scrollToBottom()
              } else {
                wx.showToast({ title: '发送失败', icon: 'none' })
              }
            },
            fail: function () { wx.showToast({ title: '发送失败', icon: 'none' }) },
            complete: function () { that.setData({ sendingImage: false }) }
          })
        },
        fail: function () {
          wx.showToast({ title: '上传失败', icon: 'none' })
          that.setData({ sendingImage: false })
        }
      })
    }).catch(function() {
      wx.showToast({ title: '图片压缩失败', icon: 'none' })
      that.setData({ sendingImage: false })
    })
  },

  // 预览大图
  previewImage: function (e) {
    var url = e.currentTarget.dataset.url
    if (url) wx.previewImage({ urls: [url], current: url })
  },

  // 初始化表情数据（懒加载，只在第一次打开时设置）
  initEmoji: function () {
    this.setData({
      emojiTabs: EMOJI_TABS,
      emojiList: EMOJI_DATA.smile
    })
  },

  // 切换表情面板显示
  toggleEmoji: function () {
    var show = !this.data.showEmoji
    if (show && this.data.emojiList.length === 0) {
      this.initEmoji()
    }
    this.setData({ showEmoji: show })
  },

  // 切换表情分类
  switchEmojiTab: function (e) {
    var tabName = e.currentTarget.dataset.tab
    if (EMOJI_DATA[tabName]) {
      this.setData({ emojiList: EMOJI_DATA[tabName] })
    }
  },

  // 选择表情
  selectEmoji: function (e) {
    var emoji = e.currentTarget.dataset.emoji
    if (emoji) {
      this.setData({
        inputText: this.data.inputText + emoji
      })
    }
  }
})
